import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String key = in.next(), text = in.next();
        // key itself plus every string one adjacent swap away from it
        Set<String> variants = new HashSet<>();
        variants.add(key);
        for (int i = 0; i + 1 < key.length(); i++) {
            char[] t = key.toCharArray();
            char c = t[i];
            t[i] = t[i + 1];
            t[i + 1] = c;
            variants.add(new String(t));
        }
        int answer = 0, m = key.length();
        for (int i = 0; i + m <= text.length(); i++) if (variants.contains(text.substring(i, i + m))) answer++;
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var key, text string
	fmt.Scan(&key, &text)
	// key itself plus every string one adjacent swap away from it
	variants := map[string]bool{key: true}
	for i := 0; i+1 < len(key); i++ {
		t := []byte(key)
		t[i], t[i+1] = t[i+1], t[i]
		variants[string(t)] = true
	}
	answer := 0
	for i := 0; i+len(key) <= len(text); i++ {
		if variants[text[i:i+len(key)]] {
			answer++
		}
	}
	fmt.Println(answer)
}
